using LUMAR_ERP_API_V2.Authorization; using LUMAR_ERP_API_V2.DTOs.Auth; using LUMAR_ERP_API_V2.DTOs.Suppliers; using LUMAR_ERP_API_V2.Services; using Microsoft.AspNetCore.Mvc; namespace LUMAR_ERP_API_V2.Controllers;
[ApiController][Route("suppliers")]public sealed class SuppliersController(ISupplierService s,IAuthenticatedUserContext userContext,Es7OperationalAudit audit):ControllerBase { [HttpGet]public async Task<ActionResult<IReadOnlyList<SupplierListDto>>> All(CancellationToken c)=>Ok(await s.GetAllAsync(c)); [HttpGet("{id:int}")]public async Task<ActionResult<SupplierDetailsDto>> One(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(x.Value!);}[HttpPost]public async Task<ActionResult<SupplierDetailsDto>> Create(CreateSupplierRequestDto request,CancellationToken c){if(request.SourceOperationId==Guid.Empty||string.IsNullOrWhiteSpace(request.SupplierCode)||string.IsNullOrWhiteSpace(request.SupplierName))return BadRequest("بيانات المورد غير مكتملة.");var user=await userContext.GetCurrentUserAsync(c);if(user is null)return Unauthorized();if(!Es7PermissionPolicy.HasPermission(user,Es7Permission.PurchasingManage))return Forbid();try{var created=await s.CreateAsync(request,c);audit.Record(user,"SupplierCreated",request.SourceOperationId,created.SupplierId,ControllerContext.HttpContext?.TraceIdentifier??"unbound");return CreatedAtAction(nameof(One),new{id=created.SupplierId},created);}catch(InvalidOperationException exception){return Conflict(exception.Message);}catch(ArgumentException exception){return BadRequest(exception.Message);}catch(Microsoft.Data.SqlClient.SqlException exception)when(exception.Number is 2601 or 2627){return Conflict("يوجد مورد مسجل بالرمز نفسه.");}}[HttpGet("{id:int}/transactions")]public async Task<ActionResult<IReadOnlyList<SupplierTransactionDto>>> Transactions(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetTransactionsAsync(id,c));}[HttpGet("{id:int}/ledger")]public async Task<ActionResult<IReadOnlyList<SupplierLedgerEntryDto>>> Ledger(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetLedgerAsync(id,c));}[HttpGet("{id:int}/invoices")]public async Task<ActionResult<IReadOnlyList<SupplierInvoiceDto>>> Invoices(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetInvoicesAsync(id,c));}[HttpGet("{id:int}/payments")]public async Task<ActionResult<IReadOnlyList<SupplierPaymentDto>>> Payments(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetPaymentsAsync(id,c));}[HttpGet("{id:int}/payment-allocations")]public async Task<ActionResult<IReadOnlyList<SupplierPaymentAllocationDto>>> Allocations(int id,CancellationToken c){var x=await Parent(id,c);return x.Error??Ok(await s.GetAllocationsAsync(id,c));}[HttpPut("{id:int}")][HttpDelete("{id:int}")]public IActionResult Disabled()=>StatusCode(405,"Supplier update and delete operations are disabled.");private async Task<(SupplierDetailsDto? Value,ActionResult? Error)> Parent(int id,CancellationToken c){if(id<=0)return(null,BadRequest("Supplier id must be positive."));var x=await s.GetByIdAsync(id,c);return x is null?(null,NotFound()):(x,null);}}